with open("src/data/services_data.json", "r", encoding="utf-8") as f:
    data = json.load(f)

for slug, ind_projects in PROJECTS.items():
    if slug not in data:
        print(f"WARNING: {slug} not found"); continue
    for ind in data[slug].get("industries", []):
        name = ind["name"]
        if name in ind_projects:
            pname, pdesc = ind_projects[name]
            ind["projectName"] = pname
            ind["projectDescription"] = pdesc
        else:
            ind["projectName"] = f"{data[slug]['name']} for {name}"
            ind["projectDescription"] = f"Delivered a tailored {data[slug]['name']} solution for the {name} sector, driving measurable operational improvements."

with open("src/data/services_data.json", "w", encoding="utf-8") as f:
    json.dump(data, f, indent=2, ensure_ascii=False)

print("Done — project details injected for all 23 services.")
